#include "../src/AlphaSimulation.h"
#include <sstream>
#include <set>
using namespace alpha;
int checks=0;void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);++checks;std::cout<<"PASS "<<message<<std::endl;}
void advance(World& w,float seconds){for(int i=0;i<int(seconds*10)&&!w.result;++i)w.step(.1f);}
int find(World& w,Kind k,int team=0){for(auto& e:w.entities)if(e.hp>0&&e.team==team&&e.kind==k)return e.id;return -1;}
int count(World& w,Kind k,int team=0){int n=0;for(auto& e:w.entities)if(e.hp>0&&e.team==team&&e.kind==k)++n;return n;}
std::string snapshot(World& w){std::ostringstream out;w.save(out);return out.str();}
std::vector<int> army(World& w){std::vector<int> ids;for(auto& e:w.entities)if(e.hp>0&&e.team==0&&mobile(e.kind)&&e.kind!=Kind::Worker&&def(e.kind).damage>0)ids.push_back(e.id);return ids;}
void kill(World& w,int id){for(auto& e:w.entities)if(e.id==id)e.hp=0;}
int main(){try{
 std::set<std::string> layouts;
 for(int n=5;n<missionCount;++n){World w;w.startMission(n);check(w.mission==n&&w.result==0&&w.cols==96,"late mission initializes on full map");check(!w.missionObjective().empty()&&!w.questTargets().empty(),"late mission has readable objective and markers");int gold=0;for(auto& e:w.entities)if(e.kind==Kind::Mine)gold+=int(e.hp);check(gold>=30000,"late mission contains sufficient finite gold reserves");std::ostringstream signature;for(auto tile:w.terrain)signature<<int(tile);for(auto& e:w.entities)if(!mobile(e.kind)&&e.kind!=Kind::Forest)signature<<int(e.kind)<<e.pos.x<<e.pos.y;layouts.insert(signature.str());Entity probe=*w.get(2);if(n!=7)for(auto target:w.questTargets())check(w.path(probe,target,140),"objective has reachable land approach");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input)&&snapshot(copy)==saved,"late mission and objective identities save exactly");w.raidsEnabled=false;advance(w,.5f);check(!w.result,"late mission does not finish on launch");}
 check(layouts.size()==6,"all six new scenarios use distinct layouts");
 {World w;w.startMission(5);check(w.missionAllows(Kind::Ranger)&&w.missionResearchAllows(Research::Elite)&&!w.missionAllows(Kind::Siege)&&!w.missionResearchAllows(Research::Town3),"sixth mission unlocks veterans without premature advanced technology");w.raidsEnabled=false;check(w.build(2,{920,1040},Kind::Sanctuary),"sixth mission paid sanctuary begins");int sanctuary=w.entities.back().id;advance(w,30);check(w.research(sanctuary,Research::Elite),"paid veteran doctrine begins");advance(w,17);check(w.train(sanctuary,Kind::Healer),"paid healer begins");check(w.research(find(w,Kind::Barracks),Research::Barracks3),"local barracks III research begins");advance(w,17);int barracks=find(w,Kind::Barracks);check(w.train(barracks,Kind::Ranger),"first paid veteran trains");advance(w,11);check(w.train(barracks,Kind::Ranger),"second paid veteran trains");advance(w,11);check(w.missionStage==1,"real healer doctrine and veterans open archive objectives");for(int id=2;id<=4;++id)w.gather(*w.get(id),find(w,Kind::Mine,-1));for(int id=5;id<=6;++id){int tree=-1;float best=1e9;for(auto& e:w.entities)if(e.kind==Kind::Forest&&distance(e.pos,w.get(id)->pos)<best){best=distance(e.pos,w.get(id)->pos);tree=e.id;}w.gather(*w.get(id),tree);}advance(w,120);for(int i=0;i<8;++i){check(w.train(barracks,Kind::Ranger),"reinforced archive patrol paid from collected resources");advance(w,11);}check(w.research(find(w,Kind::Forge),Research::Armor),"archive army armor is paid");advance(w,13);for(int id:w.missionGuards){auto node=w.get(id);auto p=node->pos;std::vector<int> guards;for(auto& e:w.entities)if(e.hp>0&&e.team==1&&mobile(e.kind)&&distance(e.pos,p)<190)guards.push_back(e.id);for(int enemy:guards){for(int unit:army(w))if(w.get(unit))w.attack(*w.get(unit),enemy);advance(w,25);}for(int unit:army(w))if(w.get(unit))w.move(*w.get(unit),p);int healer=find(w,Kind::Healer);if(healer>0)w.move(*w.get(healer),p+sf::Vector2f(-100,100));advance(w,35);}check(w.missionStage>=2,"army recovers three archives through presence and combat");for(int unit:army(w))if(w.get(unit))w.move(*w.get(unit),w.get(w.missionGuards[1])->pos);advance(w,65);check(w.result==1,"sixth mission completes through recovery and defense");}
 {World w;w.startMission(6);w.raidsEnabled=false;check(w.missionAllows(Kind::Siege)&&!w.missionAllows(Kind::Battleship),"seventh mission adds siege before heavy ships");check(w.build(2,{950,1450},Kind::Workshop),"paid siege workshop begins");int workshop=w.entities.back().id;advance(w,35);check(w.train(workshop,Kind::Siege),"first paid siege engine begins");advance(w,17);check(w.train(workshop,Kind::Siege),"second paid siege engine begins");advance(w,17);check(w.missionStage==1,"two siege engines open depot objective");for(int id:w.missionGuards)kill(w,id);advance(w,.5f);check(w.missionStage==2,"all three destroyed depots open final assault");kill(w,find(w,Kind::Hall,1));advance(w,.5f);check(w.result==1,"seventh mission requires depot and command destruction");}
 {World w;w.startMission(7);check(w.water({1200,1570})&&!w.water({2440,1980})&&w.missionAllows(Kind::Battleship)&&w.missionAllows(Kind::Submarine),"eighth mission supports heavy navy and island objective");w.raidsEnabled=false;w.gather(*w.get(4),find(w,Kind::Mine,-1));int initialPort=find(w,Kind::Shipyard);check(w.train(initialPort,Kind::Tanker),"heavy navy tanker paid from initial bank");advance(w,11);int tanker=find(w,Kind::Tanker);check(w.build(tanker,{1200,1570},Kind::OilRig),"heavy navy platform built on finite oil");int rig=w.entities.back().id;advance(w,30);w.gather(*w.get(tanker),rig);advance(w,150);check(w.oil>=150,"heavy navy oil is actually extracted and delivered");check(w.build(2,{800,1070},Kind::Foundry),"naval foundry is reachable and paid");advance(w,30);int port=find(w,Kind::Shipyard);check(w.train(port,Kind::Battleship),"corazzata paid production begins");advance(w,21);check(w.train(port,Kind::Transport),"late naval transport paid production begins");advance(w,13);check(w.missionStage==1,"heavy fleet opens island landing objective");int transport=find(w,Kind::Transport),ship=find(w,Kind::Battleship);w.move(*w.get(transport),{900,1440});advance(w,15);auto fighters=army(w);int assigned=0;for(int id:fighters)if(w.get(id)&&def(w.get(id)->kind).domain==Domain::Land&&assigned++<6)w.board(*w.get(id),transport);advance(w,40);int aboard=0;for(auto& e:w.entities)if(e.hp>0&&e.carrier==transport)++aboard;check(aboard==6,"eighth mission army boards a real transport");w.move(*w.get(transport),{2010,1980});w.move(*w.get(ship),{2450,1740});advance(w,30);check(w.unload(transport,{2130,1980}),"eighth mission island has a navigable landing approach");std::vector<int> garrison;for(auto& e:w.entities)if(e.hp>0&&e.team==1&&mobile(e.kind)&&distance(e.pos,{2440,1980})<250)garrison.push_back(e.id);for(int enemy:garrison){for(int id:fighters)if(w.get(id)&&w.get(id)->carrier<0)w.attack(*w.get(id),enemy);w.attack(*w.get(ship),enemy);advance(w,25);}for(int id:fighters)if(w.get(id)&&w.get(id)->carrier<0)w.move(*w.get(id),{2440,1980});advance(w,40);check(w.missionStage==2,"island hold opens enemy port objective");kill(w,w.missionGuards[1]);advance(w,.5f);check(w.result==1,"eighth mission ends only after enemy port is destroyed");}
 {World w;w.startMission(8);w.raidsEnabled=false;w.gather(*w.get(4),find(w,Kind::Mine,-1));check(w.missionAllows(Kind::Mage)&&!w.missionAllows(Kind::Warbird)&&w.missionResearchAllows(Research::Town3),"ninth mission teaches magic before combat flyers");check(w.research(1,Research::Town3),"command III is paid");advance(w,23);check(w.build(2,{1150,1730},Kind::Academy),"paid arcane academy begins");int academy=w.entities.back().id;advance(w,35);check(w.research(academy,Research::Arcana),"arcane doctrine is researched");advance(w,17);check(w.train(academy,Kind::Mage),"first paid mage begins");advance(w,15);check(w.train(academy,Kind::Mage),"second paid mage begins");advance(w,15);check(w.missionStage==1,"mages and research open the sigils");for(int id:w.missionGuards){auto p=w.get(id)->pos;for(auto& e:w.entities)if(e.team==1&&mobile(e.kind)&&distance(e.pos,p)<240)e.hp=0;w.add(Kind::Soldier,0,p+sf::Vector2f(-120,0));}advance(w,12);check(w.missionStage==2,"three real sigil presences open defense");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input),"multi-objective progress and defense timer restore");advance(w,50);advance(copy,50);check(w.result==1&&copy.result==1&&snapshot(w)==snapshot(copy),"ninth defense finishes identically after loading");}
 {World w;w.startMission(9);w.raidsEnabled=false;w.gather(*w.get(4),find(w,Kind::Mine,-1));check(w.missionAllows(Kind::Warbird),"tenth mission unlocks combat flyers");check(w.build(2,{1000,1960},Kind::Hall),"second player command builds with worker");advance(w,40);check(w.build(3,{1100,1440},Kind::Aviary),"paid aviary begins");int aviary=w.entities.back().id;advance(w,35);check(w.train(aviary,Kind::Warbird),"first combat flyer trains");advance(w,21);check(w.train(aviary,Kind::Warbird),"second combat flyer trains");advance(w,21);check(w.missionStage==1,"second base and flyers open the front");for(int i=0;i<2;++i){auto p=w.get(w.missionGuards[i])->pos;for(auto& e:w.entities)if(e.team==1&&mobile(e.kind)&&distance(e.pos,p)<240)e.hp=0;w.add(Kind::Soldier,0,p+sf::Vector2f(-120,0));}advance(w,14);check(w.missionStage==2,"two recovered posts open military production targets");kill(w,w.missionGuards[2]);advance(w,.5f);check(!w.result,"one remaining military depot prevents early victory");kill(w,w.missionGuards[3]);advance(w,.5f);check(w.result==1,"tenth mission clears both production targets");}
 {World w;w.startMission(10);check(count(w,Kind::Hall,1)==3&&w.enemyRemaining()>50,"finale starts with three fortified camps and a substantial force");check(w.get(w.archivist)&&w.get(w.archivist)->team<0,"Worldstone stands in enemy camp as protected monument");check(w.upgrades[1][int(Research::Armor)]==2&&w.upgrades[1][int(Research::Arcana)]==2,"finale enemies have elite armor and magic");w.raidsEnabled=false;for(auto& e:w.entities)if(e.team==1&&e.kind==Kind::Hall)e.hp=0;advance(w,.5f);check(w.result==0&&w.questTargets().size()==size_t(w.enemyRemaining()),"destroyed commands do not win and remaining enemies are marked");int straggler=find(w,Kind::Worker,1);for(auto& e:w.entities)if(e.team==1&&e.id!=straggler)e.hp=0;w.missionStage=2;advance(w,.5f);check(!w.result&&w.enemyRemaining()==1&&!w.questTargets().empty(),"last worker prevents victory and is marked for search");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input)&&copy.enemyRemaining()==1,"final enemy and crystal state survive save");kill(w,straggler);kill(copy,straggler);advance(w,.5f);advance(copy,.5f);check(w.result==1&&copy.result==1&&w.get(w.archivist)&&snapshot(w)==snapshot(copy),"finale wins only after every enemy falls and preserves Worldstone");}
 {World w;w.startMission(10);w.enemyGold=w.enemyWood=w.enemyOil=0;for(auto& e:w.entities)if(e.team==1&&e.kind==Kind::Worker)e.hp=0;int before=w.enemyRemaining();advance(w,50);check(w.enemyRemaining()<=before,"finale cannot generate free reinforcements without resources");}
 {World w;w.startMission(10);advance(w,25);check(w.enemyRemaining()>50&&w.enemyGold<2400,"finale reinforcements consume real bank and gather resources");bool attack=false;for(auto& e:w.entities)if(e.team==1&&mobile(e.kind)&&e.order==Order::Attack)attack=true;check(!attack,"finale permits army preparation before automatic assaults");w.missionStage=1;w.wave=w.time+2;advance(w,5);attack=false;for(auto& e:w.entities)if(e.team==1&&mobile(e.kind)&&e.order==Order::Attack)attack=true;check(attack,"deadline dispatches real coordinated enemy attack");}
 {World w;w.startMission(6);auto healer=w.get(find(w,Kind::Healer));int enemy=find(w,Kind::Soldier,1);check(healer&&enemy>0,"late army includes healer and enemy target");w.attack(*healer,enemy);check(healer->order==Order::Move&&!w.canHit(*healer,*w.get(enemy)),"healer follows attack order safely without becoming an attacker");}
 std::cout<<"SUCCESS "<<checks<<" late campaign and final war checks"<<std::endl;return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
